import sys

def solve():
    input = sys.stdin.read().splitlines()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n = int(input[ptr])
        ptr += 1
        strings = input[ptr:ptr+n]
        ptr += n
        res = []
        for s in strings:
            found = False
            len_s = len(s)
            for i in range(1, len_s):
                prefix = s[:i]
                suffix = s[i:]
                if prefix in strings and suffix in strings:
                    found = True
                    break
            if not found and len_s > 0:
                for s_j in strings:
                    for s_k in strings:
                        if s == s_j + s_k:
                            found = True
                            break
                    if found:
                        break
            res.append('1' if found else '0')
        print(''.join(res))

solve()
